def upi_uri_amount(upi_uri):
    parts = upi_uri.split('?')
    if len(parts) > 1:
        params = parts[1].split('&')
        for param in params:
            if param.startswith('am='):
                try:
                    return float(param.split('=')[1])
                except ValueError:
                    return None
    return None

